import React, { useState } from 'react';
import './CSS/LoginSignup.css';

const LoginSignup = () => {
  const [state, setState] = useState("Login");
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    email: ""
  });

  const changeHandler = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const login = async () => {
    try {
      const response = await fetch('http://localhost:4000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: formData.email,
          password: formData.password
        }),
      });
      const responseData = await response.json();
      
      if (responseData.success) {
        // Update formData with the name returned from the server
        setFormData(prev => ({...prev, username: responseData.username})); 
        
        localStorage.setItem('auth-token', responseData.token);
        
        // Small delay to let the browser notice the name change before redirecting
        setTimeout(() => {
          window.location.replace("/");
        }, 100);
      } else {
        alert(responseData.errors || responseData.error);
      }
    } catch (err) {
      alert("Error connecting to server.");
    }
  };

  const signup = async () => {
    try {
      const response = await fetch('http://localhost:4000/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });
      const responseData = await response.json();
      if (responseData.success) {
        localStorage.setItem('auth-token', responseData.token);
        window.location.replace("/");
      } else {
        alert(responseData.errors);
      }
    } catch (err) {
      alert("Error connecting to server.");
    }
  };

  return (
    <div className='loginsignup'>
      <div className="loginsignup-container">
        <h1>{state}</h1>
        <form onSubmit={(e) => { e.preventDefault(); state === "Login" ? login() : signup(); }}>
          <div className="loginsignup-fields">
            
            {/* Name field ONLY for Signup */}
            {state === "Signup" && (
              <input 
                name='username' 
                value={formData.username} 
                onChange={changeHandler} 
                type="text" 
                placeholder='Your Name' 
                required 
              />
            )}
            
            {/* Email input - We tell the browser this is the "username" for the login pair */}
            <input 
              name='email' 
              value={formData.email} 
              onChange={changeHandler} 
              type="email" 
              placeholder='Email Address' 
              autoComplete="username" 
              required 
            />

            <input 
              name='password' 
              value={formData.password} 
              onChange={changeHandler} 
              type="password" 
              placeholder='Password' 
              autoComplete={state === "Signup" ? "new-password" : "current-password"} 
              required 
            />
          </div>
          <button type="submit">Continue</button>
        </form>

        <p className="loginsignup-login">
          {state === "Signup" ? "Already have an account?" : "Create an account?"}
          <span onClick={() => { setState(state === "Login" ? "Signup" : "Login") }}>
            {state === "Login" ? " Click Here" : " Login Here"}
          </span>
        </p>
        
        <div className="loginsignup-agree">
          <input type="checkbox" name='agree' id='agree' required />
          <p>By continuing, I agree to the terms of use & privacy policy.</p>
        </div>
      </div>
    </div>
  );
};

export default LoginSignup;
